        "home_news_title": "Aconteciendo en el Museo",
        "news_tag_education": "Educación",
        "news_title_school_visit": "Visita de la Escuela Estatal 20 de Setembro",
        "news_desc_school_visit": "Los estudiantes exploraron las instalaciones de la antigua central y conocieron la historia de los mineros de nuestra región en una visita guiada.",
        "news_tag_collection": "Acervo",
        "news_title_restoration": "Nueva Pieza Histórica de Minería Restaurada",
        "news_desc_restoration": "Una antigua linterna de seguridad utilizada en el siglo XX fue integrada a nuestro acervo permanente tras pasar por un minucioso proceso de restauración.",
        "news_tag_community": "Comunidad",
        "news_title_miners_meeting": "Encuentro Memorial de Exmineros del Jacuí",
        "news_desc_miners_meeting": "El museo reunió a antiguos trabajadores de la región carbonífera y a sus familias para registrar relatos y memorias esenciales de nuestro patrimonio inmaterial.",
